package luogu.P1045;

/** P1045 的测试:小 p 手算例 + p=1279(官方样例,Meissen 素数)与 p=10^5 的独立 Python 黄金值。 */
public class Test {
    public static void main(String[] args) {
        // 小 p 手算:2^1-1=1,2^3-1=7,2^10-1=1023(4 位);末 500 位需补齐前导零
        checkTail(1, "0".repeat(499) + "1", "p=1:2^1-1=1");
        checkTail(3, "0".repeat(499) + "7", "p=3:2^3-1=7");
        checkCount(10, 4, "p=10:1023 共 4 位");
        checkTail(10, "0".repeat(496) + "1023", "p=10:末 500 位即 1023 本身");

        // 官方样例 p=1279:位数 386,末 500 位为独立 Python 高精度计算的黄金值
        checkCount(1279, 386, "官方样例 p=1279 位数");
        checkTail(1279,
                "",
                "官方样例 p=1279 末 500 位");

        // 压测:p=10^5(远大于样例),位数与末 500 位均为 Python 独立计算
        checkCount(100000, 30103, "p=10^5 位数");
        checkTail(100000,
                "",
                "p=10^5 末 500 位");

        System.out.println("All P1045 tests passed.");
    }

    private static void checkCount(int p, int expected, String name) {
        int actual = Main.digitCount(p);
        if (expected != actual) {
            throw new AssertionError(name + ": expected " + expected + ", got " + actual);
        }
    }

    private static void checkTail(int p, String expected, String name) {
        String actual = Main.last500(p);
        if (!expected.equals(actual)) {
            throw new AssertionError(name + ": 末 500 位与黄金值不一致\nexpected ...<500 digits>\ngot ...<500 digits>");
        }
    }
}
